ValidationRule.errorConditionFormula:
AND(
NOT( $User.ER_BypassVR__c ),
OR(
AND(
NOT(ISBLANK( ER_Financial_Center__c )),
OR(
AND(
ISPICKVAL(ER_Financial_Center__r.ER_Type__c,'Merchant'),
RecordType.DeveloperName  != 'ER_CR_Financial_Center_Merchant'
),
AND(
ISPICKVAL(ER_Financial_Center__r.ER_Type__c,'Client'),
RecordType.DeveloperName  != 'ER_CR_Financial_Center_Client'
)
)
),
AND(
NOT(ISBLANK( ER_Store__c )),
RecordType.DeveloperName  != 'ER_CR_Store'
),
AND(
NOT(ISBLANK( ER_Delivery_Site__c)),
RecordType.DeveloperName  != 'ER_CR_Delivery_Site'
),
AND(
NOT(ISBLANK( ER_Distribution_Point__c)),
RecordType.DeveloperName  != 'ER_CR_Distribution_Point'
)
)
)
